{
  "strategy": "Implement path confinement by modifying the agent tools to gate filesystem access and updating the mission runtime to propagate the readablePaths configuration, verified by a comprehensive suite of negative and positive testing.",
  "missions": [
    {
      "id": "confine-agent-tools",
      "objective": "Modify src/agent-tools.mjs to implement path checking logic that restricts read, search, and list_files operations to the paths specified in readablePaths if present, returning structured refusals for out-of-scope access.",
      "dependsOn": [],
      "acceptanceKey": "agent-tools-compatibility",
      "focusPaths": [
        "src/agent-tools.mjs"
      ]
    },
    {
      "id": "project-readable-paths",
      "objective": "Update src/mission-runtime.mjs to accept and expose the readablePaths configuration from the mission manifest, ensuring it is correctly passed to the agent tool initialization process.",
      "dependsOn": [
        "confine-agent-tools"
      ],
      "acceptanceKey": "mission-runtime-compatibility",
      "focusPaths": [
        "src/mission-runtime.mjs"
      ]
    },
    {
      "id": "verify-path-confinement",
      "objective": "Create test/readable-paths.test.mjs to implement deterministic tests covering restricted access, directory-scoped isolation, structured refusal behavior, and verification that unrestricted behavior is preserved when readablePaths is absent.",
      "dependsOn": [
        "project-readable-paths"
      ],
      "acceptanceKey": "readable-scope",
      "focusPaths": [
        "test/readable-paths.test.mjs"
      ]
    }
  ]
}

